 return start+`<path fill="#e5e6d1" d="M0 0h400v180H0Z"/><circle cx="315" cy="37" r="46" fill="#d6ddbb"/><path d="M96 182V38m0 52c-31 0-48-20-48-36 29-1 48 17 48 36m0 41c35-2 48-21 48-38-31 0-48 15-48 38M299 183V70m0 44c-35-2-44-23-44-39 31 2 44 21 44 39m0 33c32 0 47-18 47-35-30 0-47 19-47 35" fill="#91a978" stroke="#688d66" stroke-width="3"/><path d="M199 180v-58" stroke="#bbc59b" stroke-width="17"/><path d="M145 123c0-68 105-69 105 0Z" fill="#bb7959"/><path d="M151 126h92" stroke="#8f644a" stroke-width="5" stroke-linecap="round"/><circle cx="185" cy="90" r="7" fill="#f1d9aa"/><circle cx="213" cy="109" r="9" fill="#f1d9aa"/><circle cx="171" cy="112" r="4" fill="#f1d9aa"/><path d="M0 177c45-10 82-1 119 1s74-6 110-4 74-3 171-1v7H0Z" fill="#8ea077"/><path d="M182 30c-18-23-36 7-4 13-18 23 14 33 12-2 32 16 36-20 4-15 15-23-14-27-12 4" fill="#d1aa69"/><path d="m183 32 9 11" stroke="#887751" stroke-width="3"/>`+'</svg>';
